import json, urllib.request, urllib.parse, urllib.error

headers = {'Accept': 'application/json', 'Authorization': 'Bearer YOUR_ACCESS_TOKEN', 'X-Home-CSRF': 'b9827febbfdb4eec26bc4e7f03750021d01bcf6d24e67c010e021c633ca1518b', 'Content-Type': 'image/jpeg'}
data = open("fotografie.jpg", "rb").read()
